function extract($, ctx) {
  const items = [];
  const seen = new Set();

  const $menu = $('.menu');
  if (!$menu.length) return items;

  $menu.find('.menu-section').each(function () {
    const $sec = $(this);
    const sectionTitle = $sec.find('.menu-section-header .menu-section-title').text();
    const section = sectionTitle ? cleanText(sectionTitle) : null;

    $sec.find('.menu-item').each(function () {
      const $item = $(this);
      const nameRaw = $item.find('.menu-item-title').text();
      const name = nameRaw ? cleanText(nameRaw) : null;
      if (!name) return;

      const descRaw = $item.find('.menu-item-description').text();
      const description = descRaw ? cleanText(descRaw) : null;

      let priceText = $item.find('.menu-item-price-top').text().trim();
      if (!priceText) {
        priceText = $item.find('.menu-item-price-bottom').text().trim();
      }
      const price = priceText ? parsePrice(priceText) : null;

      const key = `${section ?? ''}|${name}|${description ?? ''}|${price ?? ''}`;
      if (seen.has(key)) return;
      seen.add(key);

      items.push({ section, name, description, price });
    });
  });

  return items;
}
